const fs = require('node:fs');
const path = require('node:path');

const ENDPOINT = 'http://127.0.0.1:54685/status';
const OUTPUT_DIR = path.join(__dirname, 'results');
const OUTPUT_FILE = path.join(OUTPUT_DIR, 'status.json');

async function fetchStatus() {
  const response = await fetch(ENDPOINT);
  if (!response.ok) {
    throw new Error(`request to ${ENDPOINT} failed with status ${response.status}`);
  }
  const body = await response.json();
  if (body.status !== 200) {
    throw new Error(`unexpected status from ${ENDPOINT}: ${JSON.stringify(body.status)}`);
  }
  return body;
}

async function main() {
  const body = await fetchStatus();
  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  fs.writeFileSync(OUTPUT_FILE, `${JSON.stringify(body)}\n`, 'utf8');
  console.log(`wrote ${path.relative(process.cwd(), OUTPUT_FILE)} -> ${JSON.stringify(body)}`);
}

main().catch((error) => {
  console.error(error.message);
  process.exitCode = 1;
});

